/*
 * A293811  "Look twice to the left" sequence starting with 1,2 (see comment).
 * https://oeis.org/A293811
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by Stage 0: S = [1,2] Stage k+1: S' = S + B +
 *            B where B is S without its last element. The function below
 *            implements the sequence described in A293811
 * Range:     u8 n <= 100, u16 n <= 100, u32 n <= 100, u64 n <= 100,
 *            u128 n <= 100, big any n
 * Helpers:   get_rec
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/get_rec.h"

seq_t a(idx_t n)
{
    if (n == 1) return (seq_t)1;
    if (n == 2) return (seq_t)2;

    /* Pre‑compute lengths L[0..m] where L[0] = 2 and
       L[i+1] = 3*L[i] - 2, until L[m] >= n. */
    uint64_t L[64];
    L[0] = 2;
    int m = 0;
    while (L[m] < n) {
        ++m;
        L[m] = 3*L[m-1] - 2;
    }

    return get_rec(n, m, L);
}
